SELECT 
FROM ainer_authorization_subject_binding
WHERE issuer = #{issuer}
  AND subject_type = #{subjectType}
  AND subject_id = #{subjectId}
  AND status = 'ACTIVE'
  AND valid_from <= #{at}
  AND (valid_until IS NULL OR valid_until > #{at})
ORDER BY created_at, id

